const BEATS_BY_DURATION=Object.freeze({15:6,30:10,45:14,60:18});

function cleanText(value){return String(value??"").normalize("NFKC").replace(/\s+/gu," " ).trim();}

function prepareOneShotEdgeRequest({job_id,language_code,target_duration_seconds,narration,duration_preflight}) {
