  if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(job_id??""))) throw new Error("job_id must be a UUID");
  if(!voice) throw new Error(`Unsupported Edge language: ${language_code}`);
  if(!BEATS_BY_DURATION[target]) throw new Error(`Unsupported target duration: ${target_duration_seconds}`);
  if(!text) throw new Error("Narration is empty");
  if(duration_preflight?.exact_tts_required!==true||duration_preflight?.prediction_is_advisory!==true) throw new Error("Narration is not eligible for exact Edge measurement");
  if(Number(duration_preflight.target_duration_seconds)!==target) throw new Error("Duration preflight target mismatch");
  if(String(duration_preflight.language_code)!==language_code) throw new Error("Duration preflight language mismatch");
