}

function validateOneShotEdgeResult({request,result}) {
  if(!request?.expected||!result||typeof result!=="object") throw new Error("Invalid Edge result context");
  const duration=Number(result.duration_seconds), target=Number(request.body.target_duration_seconds), frameTolerance=1/30;
  const min=(target*0.90)-frameTolerance, max=(target*1.10)+frameTolerance;
  if(!Number.isFinite(duration)||duration<=0) throw new Error("Edge duration is invalid");
  if(duration<min-1e-9||duration>max+1e-9) throw new Error(`Measured Edge duration ${duration.toFixed(3)} is outside ${min.toFixed(3)}-${max.toFixed(3)}`);
  for(const key of ["provider","model","voice"]) if(String(result[key]??"")!==String(request.expected[key])) throw new Error(`Edge ${key} contract changed`);
  if(Number(result.rate_percent)!==0||Number(result.post_tempo_factor)!==1) throw new Error("Edge timing manipulation is forbidden");
  if(!String(result.voiceover_path??"").trim()) throw new Error("Edge voiceover_path is missing");
  if(Number(result.sample_rate)!==48000||Number(result.channels)!==2||String(result.codec_name)!=="pcm_s16le") throw new Error("Normalized Edge audio format changed");
