    const groupWeight=prefix[end]-prefix[start],lengthCost=((groupWeight-target)/target)**2,boundaryCost=k===count?0:boundaryPenalty(tokens[end-1]),tiny=end-start<2?0.4:0,cost=dp[k-1][start]+lengthCost+boundaryCost+tiny;
