function buildSupportedTokens(text,narrationSegments){
  if(!Array.isArray(narrationSegments)||!narrationSegments.length)throw new Error("Timed beats require narration provenance segments");
  const reconstructed=narrationSegments.map((segment)=>cleanText(segment?.text)).join(" ");
  if(reconstructed!==text)throw new Error("Narration provenance segments do not reconstruct narration");
  const supported=[];
  for(let index=0;index<narrationSegments.length;index++){
    const segment=narrationSegments[index]??{},evidenceId=cleanText(segment.evidence_id),segmentText=cleanText(segment.text);
    if(!evidenceId||!segmentText)throw new Error(`Narration provenance segment ${index+1} is incomplete`);
